def fa_date(d):
    # Mehr 1 1405 = 2026-09-23 ; Mehr 30d, Aban 30d, Azar 30d
    n=(d-dt.date(2026,9,23)).days
    for m,name in [(0,'مهر'),(30,'آبان'),(60,'آذر')]:
        if n < m+30: return f"{n-m+1} {name}"
