from collections import Counter
summary={k:dict(Counter(r[k] for r in rows)) for k in ["format","pillar","sector","goal"]}
json.dump({"version":"v1","range":[rows[0]["date"],rows[-1]["date"]],"summary":summary,"rows":rows},open("calendar-v1.json","w"),ensure_ascii=False,indent=1)
with open("calendar-v1.csv","w",newline="",encoding="utf-8-sig") as f:
    w=csv.writer(f); keys=["id","date_fa","weekday","time","format","pillar","sector","goal","idea","hook","cta","style","music","stories","note"]
    w.writerow(keys); [w.writerow([("، ".join(r[k]) if isinstance(r.get(k),list) else r.get(k,"")) for k in keys]) for r in rows]
